mapper.select:
SELECT J1.*,C.ORG_NAME FROM ( SELECT A.USER_ID, A.USER_PW, A.USER_NAME, A.USER_RANK, A.ORG_ID, A.COMPANY_ID, B.COMPANY_CODE, B.COMPANY_NAME, B.COMPANY_TYPE AS USER_TYPE, A.USER_PHONE, A.USER_PHONE2, A.USER_EMAIL, A.USED_YN, A.AUTH_ID, A.REG_DATE, A.updated_at FROM ( SELECT USER_ID, USER_PW, USER_NAME, USER_RANK, ORG_ID, COMPANY_ID, USER_PHONE, USER_PHONE2, USER_EMAIL, USED_YN, AUTH_ID, REG_DATE, updated_at FROM tbl_user_info where 1=1
and company_id = #{companyId}
)A INNER JOIN tbl_company_info B ON A.COMPANY_ID=B.COMPANY_ID )J1 LEFT JOIN TBL_ORG_INFO C ON J1.ORG_ID=C.ORG_ID WHERE 1=1
and reg_date between #{sDate} and #{eDate}
and company_name LIKE CONCAT('%',#{searchValue},'%')
and org_name LIKE CONCAT('%',#{searchValue},'%')
and user_name LIKE CONCAT('%',#{searchValue},'%')
and ( company_name LIKE CONCAT('%',#{searchValue},'%') or org_name LIKE CONCAT('%',#{searchValue},'%') or user_name LIKE CONCAT('%',#{searchValue},'%') )
ORDER BY reg_date desc

