	USER_NAME=#{userName}

		,USER_PW=#{userPw}

	,company_id=#{companyId}
	,org_id=#{orgId}
	,user_phone=#{userPhone}
	,user_phone2=#{userPhone2}
	,auth_id=#{authId}
	,updated_at=curdate()

WHERE `USER_ID` =#{userId}

	AND company_id = #{scopeCompanyId}

